<?php
declare(strict_types=1);require __DIR__.'/../bootstrap.php';require_login();ensure_file_workspace_schema();$title='Share Management';require __DIR__.'/../includes/header.php';$csrf=(string)($_SESSION['_csrf']??'');
?>
<style>
.share-manager{max-width:1100px;margin:0 auto}.share-manager .manager-head{display:flex;align-items:flex-start;justify-content:space-between;gap:16px;flex-wrap:wrap;margin-bottom:20px}.share-manager .manager-head h1{margin:.25rem 0}.share-manager .manager-tools{display:flex;gap:10px;flex-wrap:wrap;align-items:center}.share-manager select,.share-manager input{border:1px solid var(--border,#dce3ed);border-radius:10px;padding:10px 12px;background:var(--surface,#fff);color:inherit;min-height:42px}.share-table-wrap{overflow:auto;border:1px solid var(--border,#e3e8f0);border-radius:14px}.share-table{width:100%;border-collapse:collapse;min-width:720px}.share-table th,.share-table td{padding:13px 15px;text-align:left;border-bottom:1px solid var(--border,#edf0f5);vertical-align:middle}.share-table th{font-size:.78rem;text-transform:uppercase;letter-spacing:.06em;color:var(--muted,#68758a);background:var(--surface-soft,#f8fafc)}.share-table tr:last-child td{border-bottom:0}.share-status{display:inline-flex;align-items:center;gap:6px;border-radius:999px;padding:5px 9px;font-size:.78rem;font-weight:700;background:#edf7f1;color:#17633a}.share-status.expired{background:#fff4df;color:#8b5700}.share-status.revoked{background:#ffebee;color:#a32330}.share-actions{display:flex;gap:6px;flex-wrap:wrap}.share-actions button{border:1px solid var(--border,#dce3ed);border-radius:8px;padding:7px 9px;background:var(--surface,#fff);color:inherit;cursor:pointer}.share-actions .revoke{color:#a32330}.share-manager .empty{padding:34px;text-align:center;color:var(--muted,#68758a)}.share-manager button:focus-visible,.share-manager select:focus-visible{outline:3px solid #7aa7ff;outline-offset:2px}@media(max-width:640px){.share-manager .manager-head{display:block}.share-manager .manager-tools{margin-top:14px}.share-manager .manager-tools select{flex:1}}
</style>
<main class="share-manager">
 <div class="manager-head"><div><span class="eyebrow">SECURITY & SHARING</span><h1>Share Management</h1><p class="muted">Review active, expired, and revoked links. Revocation is enforced server-side immediately.</p></div><div class="manager-tools"><label for="shareStatusFilter" class="sr-only">Filter shares</label><select id="shareStatusFilter"><option value="all">All links</option><option value="active">Active</option><option value="expired">Expired</option><option value="revoked">Revoked</option></select><button class="btn secondary" id="refreshShares" type="button">Refresh</button></div></div>
 <section class="card"><div id="shareManagerStatus" class="muted" role="status" aria-live="polite">Loading your share links…</div><div class="share-table-wrap"><table class="share-table"><thead><tr><th>Shared item</th><th>Created</th><th>Expires</th><th>Access</th><th>Last access</th><th>Status</th><th>Actions</th></tr></thead><tbody id="shareManagerRows"><tr><td colspan="7" class="empty">Loading…</td></tr></tbody></table></div></section>
</main>
<script>
(()=>{'use strict';const csrf=<?=json_encode($csrf)?>;const rows=document.getElementById('shareManagerRows'),status=document.getElementById('shareManagerStatus'),filter=document.getElementById('shareStatusFilter');const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function request(url,options={}){const r=await fetch(url,{credentials:'same-origin',headers:{'Accept':'application/json','X-CSRF-Token':csrf,...(options.headers||{})},...options});const j=await r.json().catch(()=>({}));if(!r.ok||!j.ok)throw Error(j.error||'Request failed.');return j}
function render(items){if(!items.length){rows.innerHTML='<tr><td colspan="7" class="empty">No share links match this filter.</td></tr>';return}rows.innerHTML=items.map(x=>`<tr data-id="${Number(x.id)}"><td><strong>${esc(x.title)}</strong><div class="muted">${Number(x.item_count)||0} item(s)</div></td><td>${esc(x.created_at||'—')}</td><td>${esc(x.expires_at||'Never')}</td><td>${Number(x.downloads)||0}${Number(x.max_downloads)>0?' / '+Number(x.max_downloads):' / ∞'}</td><td>${esc(x.last_access||'No access yet')}</td><td><span class="share-status ${esc(x.status)}">${esc(x.status)}</span></td><td><div class="share-actions"><button type="button" data-action="open" data-url="${esc(x.url)}">Open</button><button type="button" data-action="copy" data-url="${esc(x.url)}">Copy</button>${x.link_id?`<button type="button" data-action="analytics" data-id="${Number(x.link_id)}">Analytics</button>`:''}${x.status==='revoked'?'':`<button type="button" class="revoke" data-action="revoke" data-id="${Number(x.id)}">Revoke</button>`}${(!x.expires_at||new Date(x.expires_at.replace(' ','T'))>new Date())?`<button type="button" data-action="regenerate" data-id="${Number(x.id)}">Regenerate</button>`:''}</div></td></tr>`).join('')}
async function load(){status.textContent='Loading share links…';rows.innerHTML='<tr><td colspan="7" class="empty">Loading…</td></tr>';try{const j=await request('/api/share-management.php?status='+encodeURIComponent(filter.value));render(j.items||[]);status.textContent=`${(j.items||[]).length} link(s) shown. Access history is based on recorded share events.`}catch(e){rows.innerHTML='<tr><td colspan="7" class="empty">Could not load share links.</td></tr>';status.textContent=e.message}}
rows.addEventListener('click',async e=>{const b=e.target.closest('button[data-action]');if(!b)return;const action=b.dataset.action;try{if(action==='open'){window.open(b.dataset.url,'_blank','noopener');return}if(action==='analytics'){window.open('/link-analytics/?id='+encodeURIComponent(b.dataset.id),'_blank','noopener');return}if(action==='copy'){await navigator.clipboard.writeText(b.dataset.url);status.textContent='Share link copied.';return}if(action==='revoke'){if(!confirm('Revoke this link now? Anyone using it will lose access immediately.'))return;await request('/api/share-management.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({_csrf:csrf,action:'revoke',id:Number(b.dataset.id)})});status.textContent='Share revoked.';await load();return}if(action==='regenerate'){if(!confirm('Regenerate this link? The existing URL will stop working.'))return;const j=await request('/api/share-management.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({_csrf:csrf,action:'regenerate',id:Number(b.dataset.id)})});await navigator.clipboard.writeText(j.url);status.textContent='A new link was generated and copied.';await load()}}catch(err){status.textContent=err.message||'Action failed.'}});filter.addEventListener('change',load);document.getElementById('refreshShares').addEventListener('click',load);load();})();
</script>
<?php require __DIR__.'/../includes/footer.php'; ?>
